select n.nspname,c.relname,c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='clock_private' and c.relkind='r';
select has_function_privilege('anon','public.clock_start(uuid)','EXECUTE') as anon_start_false,has_function_privilege('authenticated','public.clock_start(uuid)','EXECUTE') as authenticated_start_true,has_function_privilege('anon','public.clock_leaderboard()','EXECUTE') as leaderboard_true,has_schema_privilege('authenticated','clock_private','USAGE') as direct_access_false;
select * from public.clock_leaderboard();